items.check_script:
# -*- coding: utf-8 -*-

from items.common._base import BaseCheck


VMSTAT_COMMAND = 'vmstat'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'ssh'

    def parse_output(self, output):
        lines = [line.strip() for line in (output or '').splitlines() if line.strip()]

        for index, line in enumerate(lines):
            headers = line.split()
            if not all(name in headers for name in ('us', 'sy', 'id', 'wa')):
                continue

            if index + 1 >= len(lines):
                return {'failure_type': 'parse_failure', 'reason': 'vmstat data row was not found.'}

            values = lines[index + 1].split()
            if len(headers) != len(values):
                return {'failure_type': 'parse_failure', 'reason': 'vmstat header/data column count mismatch.'}

            try:
                idle_percent = float(values[headers.index('id')])
                io_wait_percent = float(values[headers.index('wa')])
            except Exception:
                return {'failure_type': 'parse_failure', 'reason': 'vmstat id/wa value is not numeric.'}

            return {
                'cpu_usage_percent': round(100.0 - idle_percent, 1),
                'io_wait_percent': round(io_wait_percent, 1),
                'idle_percent': round(idle_percent, 1),
            }

        return {'failure_type': 'parse_failure', 'reason': 'vmstat cpu header was not found.'}

    def evaluate(self, metrics, max_cpu_percent, max_io_wait_percent):
        if metrics.get('failure_type'):
            return 'fail'
        if metrics['cpu_usage_percent'] > max_cpu_percent:
            return 'fail'
        if metrics['io_wait_percent'] > max_io_wait_percent:
            return 'fail'
        return 'ok'

    def build_result(self, metrics, max_cpu_percent, max_io_wait_percent, status):
        criteria = (
            'ok: CPU usage <= %.1f%% and I/O wait <= %.1f%%; '
            'fail: command failure, parsing failure, or threshold exceeded'
        ) % (max_cpu_percent, max_io_wait_percent)

        if metrics.get('failure_type') == 'command_failure':
            return {
                'message': 'vmstat command execution failed.',
                'results': metrics.get('reason', 'command failed'),
                'criteria': criteria,
            }

        if metrics.get('failure_type') == 'parse_failure':
            return {
                'message': 'vmstat output parsing failed.',
                'results': metrics.get('reason', 'parsing failed'),
                'criteria': criteria,
            }

        results = 'CPU usage %.1f%%, I/O wait %.1f%%, idle %.1f%%' % (
            metrics['cpu_usage_percent'],
            metrics['io_wait_percent'],
            metrics['idle_percent'],
        )

        if status == 'ok':
            message = 'vmstat CPU usage check passed.'
        else:
            message = 'vmstat CPU usage check failed policy.'

        return {
            'message': message,
            'results': results,
            'criteria': criteria,
        }

    def run(self):
        max_cpu_percent = self.get_threshold_var('max_cpu_percent', default=70.0, value_type='float')
        max_io_wait_percent = self.get_threshold_var('max_io_wait_percent', default=10.0, value_type='float')

        rc, output, error = self._ssh(VMSTAT_COMMAND)

        if rc != 0:
            metrics = {
                'failure_type': 'command_failure',
                'rc': rc,
                'reason': (error or output or 'vmstat command failed').strip(),
            }
        else:
            metrics = self.parse_output(output)

        status = self.evaluate(metrics, max_cpu_percent, max_io_wait_percent)
        result = self.build_result(metrics, max_cpu_percent, max_io_wait_percent, status)

        return self.result(
            status=status,
            message=result['message'],
            metrics=metrics,
            results=result['results'],
            criteria=result['criteria'],
        )


CHECK_CLASS = Check
